exec(open('/home/claude/work/gita/gc.py').read())
def VB(lab,items,cap):
    d=min(22,118//len(items))
    return S(lab,'K',None,cap,B,''.join(T(160,46+k*d,t,9) for k,t in enumerate(items)))
V=[
X(1,'HEAR AGAIN',
 S('Krishna speaking warmly to a delighted Arjuna','KA','heart','PRĪYAMĀṆA'),
 'The Lord said: Hear again, mighty-armed one, my supreme word, which I will speak to you, who delight in it, wishing your good.',
 [('bhūyaḥ eva mahā-bāho','<b>again, mighty-armed one</b>'),('śṛṇu me paramam vacaḥ','<b>hear my supreme word</b>'),('yat te aham prīyamāṇāya','<b>which to you, who delight</b>'),('vakṣyāmi hita-kāmyayā','<b>I will speak, wishing your good</b>')],
 'Kṛṣṇa continues, encouraged by Arjuna’s delight.',
 'The teacher speaks more because the student enjoys listening. Commentators note <i>hita-kāmyayā</i>: everything Kṛṣṇa says is for Arjuna’s good.',
 'A willing listener draws out the best from a teacher.',
 'Spoken <b>for your good</b>.'),
X(2,'NOT EVEN THE GODS KNOW',
 S('Gods and sages puzzled, looking for the source','','gods','WHO KNOWS?'),
 '“Neither the hosts of gods nor the great sages know my origin; for I am in every way the source of the gods and the great sages.”',
 [('na me viduḥ sura-gaṇāḥ','<b>the hosts of gods do not know</b>'),('prabhavam na mahā-ṛṣayaḥ','<b>my origin, nor great sages</b>'),('aham ādiḥ hi devānām','<b>for I am the source of the gods</b>'),('maharṣīṇām ca sarvaśaḥ','<b>and of the great sages, in every way</b>')],
 'Even gods and sages cannot know God’s origin, since he is their origin.',
 'A child cannot remember its parents’ birth. Commentators say the source is beyond its products.',
 'The deepest source is beyond full understanding. Humility is fitting.',
 'The source is <b>beyond its creations</b>.'),
X(3,'THE UNBORN, BEGINNINGLESS',
 S('A person recognising Krishna as unborn and Lord of all','Y','om','AJAM ANĀDIM'),
 '“One who knows me as unborn, beginningless, the great Lord of the worlds, is undeluded among mortals and freed from all sins.”',
 [('yaḥ mām ajam anādim ca','<b>who me as unborn, beginningless</b>'),('vetti loka-maheśvaram','<b>knows, great Lord of the worlds</b>'),('asammūḍhaḥ saḥ martyeṣu','<b>he is undeluded among mortals</b>'),('sarva-pāpaiḥ pramucyate','<b>is freed from all sins</b>')],
 'Knowing God as unborn and Lord frees one.',
 'Commentators: this knowledge removes the deepest delusion, that we and the world are self-made.',
 'Knowing there is a source beyond us brings both humility and freedom.',
 'Know me as unborn, <b>and be freed</b>.'),
X(4,'ALL QUALITIES FROM ME · I',
 VB('Qualities listed: intelligence, knowledge, truth, calm',['BUDDHI','JÑĀNA','KṢAMĀ','SATYA','ŚAMA'],'FROM ME'),
 '“Intelligence, knowledge, freedom from delusion, forbearance, truth, self-control, calm, pleasure and pain, birth and death, fear and fearlessness,”',
 [('buddhiḥ jñānam asammohaḥ','<b>intelligence, knowledge, clarity</b>'),('kṣamā satyam damaḥ śamaḥ','<b>forbearance, truth, restraint, calm</b>'),('sukham duḥkham bhavaḥ abhāvaḥ','<b>pleasure, pain, birth, death</b>'),('bhayam ca abhayam eva ca','<b>fear and fearlessness</b>')],
 'A list of human states, all arising from God.',
 'The list includes opposites: pleasure and pain, fear and fearlessness. Commentators: the source of all states is one; even hard ones serve a purpose. The sentence continues.',
 'Even your difficult feelings arise from the same source as your best ones.',
 'All states <b>arise from me</b>.'),
X(5,'ALL QUALITIES FROM ME · II',
 VB('More qualities: non-violence, equanimity, contentment',['AHIṂSĀ','SAMATĀ','TUṢṬI','TAPAS','DĀNA'],'FROM ME'),
 '“…non-violence, equanimity, contentment, austerity, charity, fame and infamy: these various states of beings arise from me alone.”',
 [('ahiṃsā samatā tuṣṭiḥ','<b>non-violence, equanimity, contentment</b>'),('tapaḥ dānam yaśaḥ ayaśaḥ','<b>austerity, charity, fame, infamy</b>'),('bhavanti bhāvāḥ bhūtānām','<b>arise, the states of beings</b>'),('mattaḥ eva pṛthak-vidhāḥ','<b>from me alone, in variety</b>')],
 'The list completes: every quality comes from the Lord.',
 '<i>Ahiṃsā</i> heads the list, as in many Indian lists of virtues. Commentators note fame and infamy too come from him.',
 'Cultivate the good qualities; know their source.',
 'Every quality <b>has one source</b>.'),
X(6,'THE SEVEN SAGES AND THE MANUS',
 S('Seven sages and four Manus born from Krishna’s mind','','sage','MĀNASĀḤ'),
 '“The seven great sages and the four before them, and the Manus, were born of my mind, filled with my nature; from them come these creatures of the world.”',
 [('mahā-ṛṣayaḥ sapta pūrve','<b>the seven great sages, of old</b>'),('catvāraḥ manavaḥ tathā','<b>the four, and the Manus</b>'),('mat-bhāvāḥ mānasāḥ jātāḥ','<b>of my nature, born of my mind</b>'),('yeṣām loke imāḥ prajāḥ','<b>from whom are these creatures</b>')],
 'The ancestors of humanity were born of God’s mind.',
 'The phrase can be read as “the seven great sages, the four earlier ones (the Sanakas), and the Manus”, or “the seven sages of old, and the four Manus”. Commentators differ. The point: all lineages trace back to God.',
 'Every family tree goes back to one source.',
 'All lineages <b>from my mind</b>.'),
X(7,'KNOWING MY GLORY',
 S('A devotee seeing Krishna’s glory and becoming steady','Y','light','VIBHŪTI · YOGA'),
 '“One who truly knows this glory and power of mine is united with unwavering yoga; of this there is no doubt.”',
 [('etām vibhūtim yogam ca','<b>this glory and power</b>'),('mama yaḥ vetti tattvataḥ','<b>of mine, who knows truly</b>'),('saḥ avikampena yogena','<b>he, with unwavering yoga</b>'),('yujyate na atra saṃśayaḥ','<b>is united, no doubt</b>')],
 'Knowing God’s glory steadies devotion.',
 '<i>Vibhūti</i>, divine glory, names this chapter. Commentators say seeing God’s glory everywhere keeps the mind from wavering.',
 'Look for the Divine in what is excellent around you.',
 'Know my glory, <b>be steady</b>.'),
X(8,'THE ORIGIN OF ALL',
 S('The wise worshipping Krishna as the origin of everything','K','seed','AHAM PRABHAVAḤ'),
 '“I am the origin of all; from me everything proceeds. Knowing this, the wise worship me, full of feeling.”',
 [('aham sarvasya prabhavaḥ','<b>I am the origin of all</b>'),('mattaḥ sarvam pravartate','<b>from me all proceeds</b>'),('iti matvā bhajante mām','<b>thinking thus, they worship me</b>'),('budhāḥ bhāva-samanvitāḥ','<b>the wise, full of feeling</b>')],
 'Verses 10.8–11 are called the four core verses of the Gītā in some traditions.',
 'Gauḍīya Vaiṣṇavas especially call 10.8–11 the <i>catuḥślokī</i>, four-verse essence. <i>Bhāva</i>, feeling, shows that wisdom and emotion join in devotion.',
 'Knowledge and love are not opposites. The wise love deeply.',
 'I am <b>the origin of all</b>.'),
X(9,'DELIGHTING TOGETHER',
 S('Devotees sharing stories of Krishna, delighted','P','family','BODHAYANTAḤ'),
 '“With minds on me, their lives given to me, enlightening one another and always speaking of me, they are content and delight.”',
 [('mat-cittāḥ mat-gata-prāṇāḥ','<b>minds on me, lives given to me</b>'),('bodhayantaḥ parasparam','<b>enlightening one another</b>'),('kathayantaḥ ca mām nityam','<b>always speaking of me</b>'),('tuṣyanti ca ramanti ca','<b>they are content and delight</b>')],
 'The joy of devotees in company.',
 'This verse is the basis of <i>satsaṅga</i>, good company. Commentators: sharing devotion multiplies it.',
 'Seek company that lifts you. Share what inspires you.',
 'Devotees <b>delight together</b>.'),
X(10,'I GIVE THE UNDERSTANDING',
 S('Krishna giving a lamp of understanding to devotees','K','lamp','BUDDHI-YOGA'),
 '“To those ever united and worshipping me with love, I give the yoga of understanding by which they come to me.”',
 [('teṣām satata-yuktānām','<b>to those ever united</b>'),('bhajatām prīti-pūrvakam','<b>worshipping with love</b>'),('dadāmi buddhi-yogam tam','<b>I give that yoga of understanding</b>'),('yena mām upayānti te','<b>by which they come to me</b>')],
 'God himself gives understanding to the loving.',
 'Grace meets effort. Commentators: the devotee need not struggle alone; understanding is given.',
 'Love first; understanding is given along the way.',
 'To the loving, <b>I give understanding</b>.'),
X(11,'THE LAMP OF KNOWLEDGE',
 S('Krishna in a heart lighting a lamp that drives away darkness','K','lamp','JÑĀNA-DĪPA'),
 '“Out of compassion for them, dwelling in their hearts, I destroy the darkness born of ignorance with the shining lamp of knowledge.”',
 [('teṣām eva anukampā-artham','<b>out of compassion for them</b>'),('aham ajñāna-jam tamaḥ','<b>I, the darkness born of ignorance</b>'),('nāśayāmi ātma-bhāva-sthaḥ','<b>destroy, dwelling in their hearts</b>'),('jñāna-dīpena bhāsvatā','<b>with the shining lamp of knowledge</b>')],
 'God lights a lamp in the devotee’s heart.',
 'A beloved image: God within lights the lamp. Commentators of all schools quote this verse.',
 'In the dark moments, remember: there is a lamp within.',
 'A <b>lamp lit in the heart</b>.'),
X(12,'“YOU ARE THE SUPREME BRAHMAN”',
 S('Arjuna praising Krishna with folded hands','KA','om','PARAM BRAHMA'),
 'Arjuna said: You are the supreme Brahman, the supreme abode, the supreme purifier; the eternal divine Person, the first of gods, unborn, all-pervading.',
 [('param brahma param dhāma','<b>supreme Brahman, supreme abode</b>'),('pavitram paramam bhavān','<b>you are the supreme purifier</b>'),('puruṣam śāśvatam divyam','<b>eternal divine Person</b>'),('ādi-devam ajam vibhum','<b>first god, unborn, all-pervading</b>')],
 'Arjuna responds with praise.',
 'Arjuna now speaks as a devotee, not a doubter. Commentators note the change from chapter 1.',
 'Gratitude naturally becomes praise.',
 'Arjuna: <b>you are the Supreme</b>.'),
X(13,'THE SAGES SAID SO',
 S('Sages Narada, Asita Devala and Vyasa speaking of Krishna','','sage','NĀRADA · VYĀSA'),
 '“All the sages say this of you, the divine sage Nārada, and Asita, Devala and Vyāsa; and you yourself tell me so.”',
 [('āhuḥ tvām ṛṣayaḥ sarve','<b>all the sages call you so</b>'),('deva-ṛṣiḥ nāradaḥ tathā','<b>the divine sage Nārada too</b>'),('asitaḥ devalaḥ vyāsaḥ','<b>Asita, Devala, Vyāsa</b>'),('svayam ca eva bravīṣi me','<b>and you yourself tell me</b>')],
 'Arjuna cites the sages as witnesses.',
 'Vyāsa is traditionally the author of the Mahābhārata itself. Commentators note scripture and direct teaching agree.',
 'When the wise agree, it strengthens faith.',
 'The sages <b>said so too</b>.'),
X(14,'I ACCEPT ALL YOU SAY',
 S('Arjuna nodding, accepting every word','A','heart','SARVAM ṚTAM'),
 '“I accept as true all that you tell me, Keśava. Neither the gods nor the demons, Lord, know your manifestation.”',
 [('sarvam etat ṛtam manye','<b>I hold all this as true</b>'),('yat mām vadasi keśava','<b>what you tell me, Keśava</b>'),('na hi te bhagavan vyaktim','<b>your manifestation, Lord</b>'),('viduḥ devāḥ na dānavāḥ','<b>neither gods nor demons know</b>')],
 'Arjuna’s faith grows.',
 'Commentators note the contrast with 1.31, where Arjuna saw only bad omens. Now he accepts.',
 'Trust grows step by step through understanding.',
 '<b>I accept all you say</b>.'),
X(15,'ONLY YOU KNOW YOURSELF',
 S('Krishna alone knowing himself, a circle of light','K','light','PURUṢOTTAMA'),
 '“You alone know yourself by yourself, Supreme Person, source of beings, Lord of beings, God of gods, Lord of the world.”',
 [('svayam eva ātmanā ātmānam','<b>yourself, by yourself, yourself</b>'),('vettha tvam puruṣottama','<b>you know, Supreme Person</b>'),('bhūta-bhāvana bhūta-īśa','<b>source and Lord of beings</b>'),('deva-deva jagat-pate','<b>God of gods, Lord of the world</b>')],
 'Only God fully knows God.',
 '<i>Puruṣottama</i>, Supreme Person, is fully explained in chapter 15. Commentators: we know God only as he reveals himself.',
 'Some knowledge comes only as a gift.',
 'Only you <b>know yourself</b>.'),
X(16,'TELL ME YOUR GLORIES',
 S('Arjuna asking eagerly to hear the glories','A','star','TELL ME!'),
 '“Please tell me fully your divine glories, by which you pervade these worlds and abide in them.”',
 [('vaktum arhasi aśeṣeṇa','<b>please tell fully</b>'),('divyāḥ hi ātma-vibhūtayaḥ','<b>your divine glories</b>'),('yābhiḥ vibhūtibhiḥ lokān','<b>by which glories the worlds</b>'),('imān tvam vyāpya tiṣṭhasi','<b>you pervade and abide</b>')],
 'Arjuna asks to hear the glories.',
 'Commentators note Arjuna’s eagerness: devotion wants to know more about the beloved.',
 'Love is curious about its beloved.',
 'Tell me <b>your glories</b>.'),
X(17,'HOW SHALL I THINK OF YOU?',
 S('Arjuna meditating, wondering which form to hold','A','mind','HOW?'),
 '“How may I know you, yogi, always meditating on you? In what various forms are you to be thought of by me, Lord?”',
 [('katham vidyām aham yogin','<b>how may I know you, yogi</b>'),('tvām sadā paricintayan','<b>always meditating on you</b>'),('keṣu keṣu ca bhāveṣu','<b>in which forms</b>'),('cintyaḥ asi bhagavan mayā','<b>are you to be thought of by me</b>')],
 'A practical question: what should I meditate on?',
 'Commentators: the vibhūtis give the mind concrete supports for remembering God throughout the day.',
 'Choose specific reminders of the Divine in daily life.',
 'Where shall I <b>see you</b>?'),
X(18,'I NEVER TIRE OF THIS NECTAR',
 S('Arjuna drinking nectar from Krishna’s words, never satisfied','A','heart','AMṚTA'),
 '“Tell me again in detail of your power and glory, Janārdana; for I am never satisfied hearing your nectar-like words.”',
 [('vistareṇa ātmanaḥ yogam','<b>in detail your power</b>'),('vibhūtim ca janārdana','<b>and glory, Janārdana</b>'),('bhūyaḥ kathaya','<b>tell again</b>'),('tṛptiḥ hi śṛṇvataḥ na asti me amṛtam','<b>hearing the nectar, I am never satisfied</b>')],
 'Arjuna cannot hear enough.',
 'Devotional traditions love this verse: hearing about God is nectar that never satiates.',
 'Some things are worth hearing again and again.',
 'Never tired <b>of this nectar</b>.'),
X(19,'THE CHIEF GLORIES',
 S('Krishna about to list his glories, infinite light behind','K','star','NO END'),
 'The Lord said: Yes, I will tell you my divine glories, best of the Kurus, the chief ones; for there is no end to my extent.',
 [('hanta te kathayiṣyāmi','<b>yes, I will tell you</b>'),('divyāḥ hi ātma-vibhūtayaḥ','<b>my divine glories</b>'),('prādhānyataḥ kuru-śreṣṭha','<b>the chief ones</b>'),('na asti antaḥ vistarasya me','<b>there is no end to my extent</b>')],
 'Kṛṣṇa will give only the main ones; the full list is endless.',
 'The list that follows (10.20–39) picks the best in each class. Commentators say it trains the eye to see the Divine in excellence.',
 'Notice excellence around you. Each is a glimpse.',
 'Only the chief ones: <b>there is no end</b>.'),
X(20,'THE SELF IN ALL HEARTS',
 S('Krishna in the heart of every being','K','heart','HṚDAYA'),
 '“I am the Self, Guḍākeśa, seated in the heart of all beings. I am the beginning, the middle and the end of beings.”',
 [('aham ātmā guḍākeśa','<b>I am the Self</b>'),('sarva-bhūta-āśaya-sthitaḥ','<b>seated in the heart of all beings</b>'),('aham ādiḥ ca madhyam ca','<b>I am the beginning and middle</b>'),('bhūtānām antaḥ eva ca','<b>and end of beings</b>')],
 'The first and greatest glory: God in every heart.',
 'Before naming outer glories, Kṛṣṇa names the inner one. Commentators: the highest meditation is on the Self within.',
 'The first place to look for the Divine is within.',
 'I am <b>in every heart</b>.'),
X(21,'VIṢṆU, THE SUN, THE MOON',
 VB('Vishnu among Adityas, the sun, Marici, the moon',['VIṢṆU','SUN','MARĪCI','MOON'],'AMONG…'),
 '“Of the Ādityas I am Viṣṇu; of lights, the radiant sun; of the Maruts I am Marīci; of the stars, I am the moon.”',
 [('ādityānām aham viṣṇuḥ','<b>of the Ādityas, Viṣṇu</b>'),('jyotiṣām raviḥ aṃśumān','<b>of lights, the radiant sun</b>'),('marīciḥ marutām asmi','<b>of the Maruts, Marīci</b>'),('nakṣatrāṇām aham śaśī','<b>of the stars, the moon</b>')],
 'The best of each group in the heavens.',
 'The twelve Ādityas are solar deities, Viṣṇu (as Vāmana) among them. The Maruts are storm gods. The moon is “among the nakṣatras”, the lunar mansions.',
 'Look at the sun and moon, and remember.',
 'Viṣṇu, <b>the sun, the moon</b>.'),
X(22,'SĀMAVEDA, INDRA, MIND',
 VB('Samaveda, Indra, the mind, consciousness',['SĀMA','INDRA','MIND','CETANĀ'],'AMONG…'),
 '“Of the Vedas I am the Sāmaveda; of the gods, Vāsava (Indra); of the senses, I am the mind; in beings, I am consciousness.”',
 [('vedānām sāma-vedaḥ asmi','<b>of the Vedas, Sāmaveda</b>'),('devānām asmi vāsavaḥ','<b>of the gods, Indra</b>'),('indriyāṇām manaḥ ca asmi','<b>of the senses, the mind</b>'),('bhūtānām asmi cetanā','<b>in beings, consciousness</b>')],
 'The best Veda, god, sense, and the spark of awareness.',
 'The Sāmaveda is the musical Veda, sung. Commentators note the mind as chief of the senses, and consciousness as the very life of beings.',
 'Music, mind and awareness: all are glimpses of the Divine.',
 'The sung Veda, <b>the mind, awareness</b>.'),
X(23,'ŚIVA, KUBERA, FIRE, MERU',
 VB('Shiva, Kubera, Agni, Mount Meru',['ŚAṄKARA','KUBERA','AGNI','MERU'],'AMONG…'),
 '“Of the Rudras I am Śaṅkara; of yakṣas and rākṣasas, the lord of wealth (Kubera); of the Vasus I am fire; of mountain peaks, Meru.”',
 [('rudrāṇām śaṅkaraḥ ca asmi','<b>of the Rudras, Śaṅkara</b>'),('vitta-īśaḥ yakṣa-rakṣasām','<b>of yakṣas and rākṣasas, Kubera</b>'),('vasūnām pāvakaḥ ca asmi','<b>of the Vasus, fire</b>'),('meruḥ śikhariṇām aham','<b>of peaks, Meru</b>')],
 'Śiva among the Rudras: the Gītā sees Śiva as a glory of the one Lord.',
 'Commentators of different schools read this differently: Vaiṣṇavas see Śiva as a manifestation; Smārtas see one God in both. Meru is the cosmic mountain at the centre of the world.',
 'Different names, one Divine. Respect all.',
 'Śiva, Kubera, <b>fire, Meru</b>.'),
X(24,'BṚHASPATI, SKANDA, OCEAN',
 VB('Brihaspati, Skanda, the ocean',['BṚHASPATI','SKANDA','OCEAN'],'AMONG…'),
 '“Of household priests, Pārtha, know me as the chief, Bṛhaspati; of generals I am Skanda; of bodies of water, I am the ocean.”',
 [('purodhasām ca mukhyam mām','<b>of priests, the chief</b>'),('viddhi pārtha bṛhaspatim','<b>know me as Bṛhaspati</b>'),('senānīnām aham skandaḥ','<b>of generals, Skanda</b>'),('sarasām asmi sāgaraḥ','<b>of waters, the ocean</b>')],
 'The best priest, the best general, the greatest water.',
 'Bṛhaspati is guru of the gods. Skanda (Kārttikeya, Subrahmaṇya) is the divine general (see our Subrahmaṇya Ṣaṣṭhī series).',
 'Excellence in any role, teacher or leader, reflects the Divine.',
 'The guru, <b>the general, the ocean</b>.'),
X(25,'BHṚGU, OṂ, JAPA, HIMĀLAYA',
 VB('Bhrigu, Om, japa, the Himalaya',['BHṚGU','OṂ','JAPA','HIMĀLAYA'],'AMONG…'),
 '“Of great sages I am Bhṛgu; of words, I am the one syllable (Oṃ); of sacrifices, I am the sacrifice of japa; of immovable things, the Himālaya.”',
 [('maharṣīṇām bhṛguḥ aham','<b>of great sages, Bhṛgu</b>'),('girām asmi ekam akṣaram','<b>of words, the one syllable</b>'),('yajñānām japa-yajñaḥ asmi','<b>of sacrifices, japa</b>'),('sthāvarāṇām himālayaḥ','<b>of the immovable, the Himālaya</b>')],
 'Japa, the quiet repetition of a sacred name, is the best yajña.',
 'Commentators note japa needs no materials and harms no one: the simplest and purest sacrifice. Oṃ is the best of words.',
 'Repeating a sacred name quietly is a sacrifice anyone can offer.',
 'Of sacrifices, <b>japa</b>.'),
X(26,'AŚVATTHA, NĀRADA, KAPILA',
 VB('The ashvattha tree, Narada, Chitraratha, Kapila',['AŚVATTHA','NĀRADA','CITRARATHA','KAPILA'],'AMONG…'),
 '“Of all trees I am the aśvattha (sacred fig); of divine sages, Nārada; of gandharvas, Citraratha; of the perfected, the sage Kapila.”',
 [('aśvatthaḥ sarva-vṛkṣāṇām','<b>of all trees, the aśvattha</b>'),('deva-ṛṣīṇām ca nāradaḥ','<b>of divine sages, Nārada</b>'),('gandharvāṇām citrarathaḥ','<b>of gandharvas, Citraratha</b>'),('siddhānām kapilaḥ muniḥ','<b>of the perfected, sage Kapila</b>')],
 'The sacred fig, the wandering sage, the celestial musician, the founder of Sāṅkhya.',
 'The aśvattha (peepal) is worshipped across India; it returns in 15.1. Kapila is the founder of Sāṅkhya philosophy. Nārada roams the worlds singing God’s names.',
 'Look at a peepal tree and remember.',
 'The sacred fig, <b>Nārada, Kapila</b>.'),
X(27,'THE HORSE, THE ELEPHANT, THE KING',
 VB('Uchchaihshravas the horse, Airavata the elephant, a king',['UCCAIḤŚRAVAS','AIRĀVATA','KING'],'AMONG…'),
 '“Of horses know me as Uccaiḥśravas, born of the nectar; of lordly elephants, Airāvata; and of men, the king.”',
 [('uccaiḥśravasam aśvānām','<b>of horses, Uccaiḥśravas</b>'),('viddhi mām amṛta-udbhavam','<b>know me, born of the nectar</b>'),('airāvatam gaja-indrāṇām','<b>of elephants, Airāvata</b>'),('narāṇām ca nara-adhipam','<b>of men, the king</b>')],
 'Both creatures came from the churning of the ocean.',
 'Uccaiḥśravas, the seven-headed horse, and Airāvata, Indra’s white elephant, emerged from the churning of the ocean of milk. The just king is a glory among humans.',
 'Good leadership is a reflection of the Divine.',
 'Of men, <b>the righteous king</b>.'),
X(28,'VAJRA, KĀMADHENU, VĀSUKI',
 VB('The thunderbolt, the wish-cow, Kandarpa, Vasuki',['VAJRA','KĀMADHUK','KANDARPA','VĀSUKI'],'AMONG…'),
 '“Of weapons I am the thunderbolt; of cows, Kāmadhuk (the wish-fulfilling cow); of procreators, I am Kandarpa; of serpents, Vāsuki.”',
 [('āyudhānām aham vajram','<b>of weapons, the thunderbolt</b>'),('dhenūnām asmi kāmadhuk','<b>of cows, the wish-cow</b>'),('prajanaḥ ca asmi kandarpaḥ','<b>of procreators, Kandarpa</b>'),('sarpāṇām asmi vāsukiḥ','<b>of serpents, Vāsuki</b>')],
 'More glories from myth and nature.',
 'Kandarpa (Kāma) is the power of love that brings children into the world: procreation within dharma is divine (compare 7.11). Vāsuki served as the rope at the churning of the ocean.',
 'The power of love that creates life is sacred.',
 'The thunderbolt, <b>the wish-cow</b>.'),
X(29,'ANANTA, VARUṆA, YAMA',
 VB('Ananta, Varuna, Aryaman, Yama',['ANANTA','VARUṆA','ARYAMĀ','YAMA'],'AMONG…'),
 '“Of nāgas I am Ananta; of water-dwellers, Varuṇa; of ancestors, Aryamā; and of those who govern, I am Yama.”',
 [('anantaḥ ca asmi nāgānām','<b>of nāgas, Ananta</b>'),('varuṇaḥ yādasām aham','<b>of water-beings, Varuṇa</b>'),('pitṝṇām aryamā ca asmi','<b>of ancestors, Aryamā</b>'),('yamaḥ saṃyamatām aham','<b>of controllers, Yama</b>')],
 'Ananta (Śeṣa), the serpent on whom Viṣṇu rests; Yama, lord of death and justice.',
 'Commentators note Yama as the best of those who restrain: death disciplines all. Ananta supports the universe.',
 'Order and discipline, even death’s, are part of the Divine.',
 'Ananta, Varuṇa, <b>Yama</b>.'),
X(30,'PRAHLĀDA, TIME, LION, GARUḌA',
 VB('Prahlada, time, the lion, Garuda',['PRAHLĀDA','TIME','LION','GARUḌA'],'AMONG…'),
 '“Of the daityas I am Prahlāda; of reckoners, I am time; of beasts, I am the lion; of birds, the son of Vinatā (Garuḍa).”',
 [('prahlādaḥ ca asmi daityānām','<b>of daityas, Prahlāda</b>'),('kālaḥ kalayatām aham','<b>of reckoners, time</b>'),('mṛgāṇām ca mṛga-indraḥ aham','<b>of beasts, the lion</b>'),('vainateyaḥ ca pakṣiṇām','<b>of birds, Garuḍa</b>')],
 'Prahlāda, a devotee born among demons: goodness can arise anywhere.',
 'Prahlāda was the son of the demon king Hiraṇyakaśipu, saved by Narasiṃha. Commentators love this inclusion: devotion is not bound by birth.',
 'Goodness can bloom in the hardest soil.',
 '<b>Prahlāda</b>: a saint among demons.'),
X(31,'WIND, RĀMA, GAṄGĀ',
 VB('The wind, Rama, the makara, the Ganga',['WIND','RĀMA','MAKARA','GAṄGĀ'],'AMONG…'),
 '“Of purifiers I am the wind; of wielders of weapons, I am Rāma; of fishes, I am the makara; of rivers, I am the Jāhnavī (Gaṅgā).”',
 [('pavanaḥ pavatām asmi','<b>of purifiers, the wind</b>'),('rāmaḥ śastra-bhṛtām aham','<b>of weapon-bearers, Rāma</b>'),('jhaṣāṇām makaraḥ ca asmi','<b>of fishes, the makara</b>'),('srotasām asmi jāhnavī','<b>of rivers, the Gaṅgā</b>')],
 'Rāma among warriors, Gaṅgā among rivers.',
 'Rāma here is usually taken as Rāma of Ayodhyā; some read Paraśurāma. The makara is a mythical sea creature. Gaṅgā is called Jāhnavī after the sage Jahnu.',
 'The fresh wind and the flowing river purify. Notice them.',
 'Rāma, <b>the Gaṅgā</b>.'),
X(32,'BEGINNING, MIDDLE AND END',
 VB('The beginning, middle and end, the science of the Self, the debate for truth',['ĀDI · MADHYA · ANTA','ADHYĀTMA','VĀDA'],'AMONG…'),
 '“Of creations I am the beginning, the end and the middle, Arjuna; of sciences, the science of the Self; of those who debate, I am the reasoning (vāda).”',
 [('sargāṇām ādiḥ antaḥ ca','<b>of creations, beginning and end</b>'),('madhyam ca eva aham arjuna','<b>and middle</b>'),('adhyātma-vidyā vidyānām','<b>of sciences, the science of Self</b>'),('vādaḥ pravadatām aham','<b>of debaters, reasoned discussion</b>')],
 'The science of the Self is the highest knowledge; honest debate for truth is divine.',
 'Indian logic distinguishes <i>vāda</i> (honest debate for truth) from <i>jalpa</i> (debate to win) and <i>vitaṇḍā</i> (mere fault-finding). Commentators: only vāda is the Lord.',
 'Argue to find the truth, not to win.',
 'Honest debate <b>for truth</b>.'),
X(33,'THE LETTER A, AND TIME',
 VB('The letter A, the dvandva compound, endless time',['A','DVANDVA','AKṢAYA KĀLA'],'AMONG…'),
 '“Of letters I am the letter A; of compounds, the dvandva (pair). I am imperishable Time; I am the dispenser, facing every direction.”',
 [('akṣarāṇām akāraḥ asmi','<b>of letters, A</b>'),('dvandvaḥ sāmāsikasya ca','<b>of compounds, the pair-compound</b>'),('aham eva akṣayaḥ kālaḥ','<b>I am imperishable time</b>'),('dhātā aham viśvato-mukhaḥ','<b>the dispenser, facing everywhere</b>')],
 'A is the first letter, present in all others.',
 '“A” begins the alphabet and is inherent in every consonant in Sanskrit script. The <i>dvandva</i> compound joins equals, like “Rāma-Kṛṣṇa”. Commentators love the linguistic touch.',
 'The first sound, the first step: the Divine is in beginnings.',
 'I am <b>the letter A</b>.'),
X(34,'DEATH AND THE FEMININE VIRTUES',
 VB('Death and seven feminine qualities',['FAME','FORTUNE','SPEECH','MEMORY','WISDOM','FIRMNESS','FORGIVENESS'],'MṚTYU · ŚRĪ'),
 '“I am all-devouring death and the origin of all that is to be; and among feminine qualities, fame, fortune, speech, memory, intelligence, steadfastness and forgiveness.”',
 [('mṛtyuḥ sarva-haraḥ ca aham','<b>I am all-taking death</b>'),('udbhavaḥ ca bhaviṣyatām','<b>and the source of what will be</b>'),('kīrtiḥ śrīḥ vāk ca nārīṇām','<b>fame, fortune, speech, of the feminine</b>'),('smṛtiḥ medhā dhṛtiḥ kṣamā','<b>memory, intelligence, firmness, forgiveness</b>')],
 'Death and birth, and seven qualities named in the feminine.',
 'In Sanskrit these words are grammatically feminine, and often personified as goddesses. Commentators note forgiveness (kṣamā) closes the list: the gentlest strength.',
 'Memory, steadiness, forgiveness: cultivate them as divine gifts.',
 'Death, and <b>seven graces</b>.'),
X(35,'GĀYATRĪ, MĀRGAŚĪRṢA, SPRING',
 VB('The Brihat Saman, Gayatri, Margashirsha, spring',['BṚHAT-SĀMA','GĀYATRĪ','MĀRGAŚĪRṢA','SPRING'],'AMONG…'),
 '“Of Sāma hymns I am the Bṛhat-sāma; of metres, the Gāyatrī; of months I am Mārgaśīrṣa; of seasons, the flowering spring.”',
 [('bṛhat-sāma tathā sāmnām','<b>of Sāma hymns, the Bṛhat-sāma</b>'),('gāyatrī chandasām aham','<b>of metres, the Gāyatrī</b>'),('māsānām mārgaśīrṣaḥ aham','<b>of months, Mārgaśīrṣa</b>'),('ṛtūnām kusuma-ākaraḥ','<b>of seasons, the flowering one</b>')],
 'Mārgaśīrṣa is the month of Gītā Jayantī.',
 'Mārgaśīrṣa (November–December) is the month in which Gītā Jayantī falls, on its bright ekādaśī. The Gāyatrī metre gives its name to the Gāyatrī mantra (see our article). Spring is the “mine of flowers”.',
 'This very season, Mārgaśīrṣa, is named by Kṛṣṇa as his own.',
 'Gāyatrī, <b>Mārgaśīrṣa, spring</b>.'),
X(36,'EVEN THE GAMBLING OF CHEATS',
 VB('Dice, splendour, victory, effort, goodness',['DICE','TEJAS','VICTORY','EFFORT','SATTVA'],'I AM…'),
 '“I am the gambling of cheats, the splendour of the splendid; I am victory, I am effort, I am the goodness of the good.”',
 [('dyūtam chalayatām asmi','<b>of cheats, the gambling</b>'),('tejaḥ tejasvinām aham','<b>splendour of the splendid</b>'),('jayaḥ asmi vyavasāyaḥ asmi','<b>I am victory, I am effort</b>'),('sattvam sattvavatām aham','<b>goodness of the good</b>')],
 'A surprising glory: even the gambling of cheats.',
 'Commentators explain: in each class, Kṛṣṇa is the most powerful; even in deceit, the power behind it is his. It is not approval of cheating. Note too the irony: the Pāṇḍavas lost all by dice.',
 'Power itself is neutral; how we use it decides good or bad.',
 'Even power <b>in cheating is his</b>.'),
X(37,'VĀSUDEVA, ARJUNA, VYĀSA',
 VB('Vasudeva, Arjuna, Vyasa, Ushana',['VĀSUDEVA','DHANAÑJAYA','VYĀSA','UŚANĀ'],'AMONG…'),
 '“Of the Vṛṣṇis I am Vāsudeva; of the Pāṇḍavas, Dhanañjaya (Arjuna); of sages I am Vyāsa; of poets, the poet Uśanā.”',
 [('vṛṣṇīnām vāsudevaḥ asmi','<b>of the Vṛṣṇis, Vāsudeva</b>'),('pāṇḍavānām dhanañjayaḥ','<b>of the Pāṇḍavas, Arjuna</b>'),('munīnām api aham vyāsaḥ','<b>of sages, Vyāsa</b>'),('kavīnām uśanā kaviḥ','<b>of poets, Uśanā</b>')],
 'Kṛṣṇa names himself, and Arjuna too, among his glories.',
 'A lovely moment: Arjuna hears himself named as a glory of God. Vyāsa, author of the epic, is also named. Uśanā is Śukrācārya, teacher of the asuras.',
 'You too can be a glory of the Divine, by living at your best.',
 'Arjuna himself <b>is my glory</b>.'),
X(38,'THE ROD, POLICY, SILENCE',
 VB('The rod of justice, wise policy, silence, knowledge',['DAṆḌA','NĪTI','MAUNA','JÑĀNA'],'I AM…'),
 '“I am the rod of those who punish, the policy of those who seek victory; of secrets I am silence, and the knowledge of the knowers.”',
 [('daṇḍaḥ damayatām asmi','<b>of punishers, the rod</b>'),('nītiḥ asmi jigīṣatām','<b>of those seeking victory, policy</b>'),('maunam ca eva asmi guhyānām','<b>of secrets, silence</b>'),('jñānam jñānavatām aham','<b>knowledge of the knowers</b>')],
 'Justice, wise strategy, silence and knowledge.',
 'Silence is the best way to keep a secret, and in spiritual life, silence is where the deepest secret is known. Commentators admire the line.',
 'Silence guards what is precious.',
 'Of secrets, <b>silence</b>.'),
X(39,'THE SEED OF ALL',
 S('A single seed from which every being sprouts','','seed','NOTHING WITHOUT ME'),
 '“Whatever is the seed of all beings, that am I, Arjuna. There is no being, moving or unmoving, that could exist without me.”',
 [('yat ca api sarva-bhūtānām','<b>and whatever of all beings</b>'),('bījam tat aham arjuna','<b>is the seed, that am I</b>'),('na tat asti vinā yat syāt','<b>there is nothing that could exist without</b>'),('mayā bhūtam cara-acaram','<b>me, moving or unmoving</b>')],
 'Nothing exists without God.',
 'This sums up the list: not just the best, but everything depends on him. Commentators repeat: the seed holds the whole tree.',
 'Everything you meet depends on the same source.',
 'Nothing exists <b>without me</b>.'),
X(40,'NO END TO MY GLORIES',
 S('An endless sky of stars, Krishna saying this is only a sample','K','star','JUST A SAMPLE'),
 '“There is no end to my divine glories, scorcher of foes. What I have told you is only a brief account of my vast glory.”',
 [('na antaḥ asti mama divyānām','<b>there is no end to my divine</b>'),('vibhūtīnām parantapa','<b>glories</b>'),('eṣaḥ tu uddeśataḥ proktaḥ','<b>this is told in brief</b>'),('vibhūteḥ vistaraḥ mayā','<b>of the extent of my glory</b>')],
 'The list is only a sample.',
 'Commentators: the purpose was to train the eye, not to complete a catalogue.',
 'The Divine is more than any list can hold.',
 'Only <b>a sample</b>.'),
X(41,'A SPARK OF MY SPLENDOUR',
 S('A spark from a great fire lighting up something excellent','','light','TEJO-AṂŚA'),
 '“Whatever is glorious, prosperous or powerful, know that it springs from a spark of my splendour.”',
 [('yat yat vibhūtimat sattvam','<b>whatever being is glorious</b>'),('śrīmat ūrjitam eva vā','<b>prosperous or mighty</b>'),('tat tat eva avagaccha tvam','<b>know that</b>'),('mama tejaḥ-aṃśa-sambhavam','<b>born of a spark of my splendour</b>')],
 'The rule: wherever there is excellence, see a spark of God.',
 'This is the method of the whole chapter, put in one line. Commentators say it lets us see God in great art, science, kindness and courage.',
 'When you admire something excellent, remember: a spark of the Divine.',
 'All excellence: <b>a spark of mine</b>.'),
X(42,'ONE FRAGMENT',
 S('Krishna holding the whole universe with one fragment of himself','K','cosmic','EKA-AṂŚENA'),
 '“But what need is there for this detailed knowledge, Arjuna? I stand, supporting this whole world with a single fragment of myself.”',
 [('athavā bahunā etena','<b>but with all this detail</b>'),('kim jñātena tava arjuna','<b>what is the use to you?</b>'),('viṣṭabhya aham idam kṛtsnam','<b>I, supporting this whole</b>'),('eka-aṃśena sthitaḥ jagat','<b>world with one fragment, stand</b>')],
 'The whole universe is only a fraction of God.',
 'This echoes the Puruṣa Sūkta: one quarter of him is all beings; three quarters are immortal (see our Puruṣa Sūktam article). It prepares for chapter 11, where Arjuna will see the cosmic form.',
 'However vast the universe, the Divine is vaster.',
 'The universe: <b>one fragment</b>.'),
]
cover=('<svg width="380" height="268" viewBox="0 0 380 268" role="img" aria-label="Krishna surrounded by his glories: the sun, the moon, Mount Meru, the Ganga, the ashvattha tree, a lion and Garuda">'
 '<rect width="380" height="268" fill="#0b2a4a" rx="8"/>'+GLOW(190,130,110,'#ffd60a',.25)+SUN(60,60,24)+MOON(320,60,18)+'<path d="M20 240 L70 150 L120 240z" fill="#9fb3c8" stroke="#111" stroke-width="2"/>'+TREE(320,240,1.3)+'<path d="M140 250 q40 -20 100 0" fill="none" stroke="#3b8fd0" stroke-width="10"/>'+KR(190,170,1.5,arms4=True)+T(190,30,'VIBHŪTI',22,'#ffd60a')+'</svg>')
P=dict(ch=10,nv=42,V=V,per=[14,14,14],out='/home/claude/work/gita/Gita_Chapter10.html',
 title='Divine Glories · Bhagavad Gītā Chapter 10 · srini.presents',
 desc='Bhagavad Gītā chapter 10, Vibhūti Yoga, every śloka explained: the four core verses, the lamp of knowledge in the heart, and Kṛṣṇa’s glories: among lights the sun, among mountains Meru, among rivers the Gaṅgā, among letters A, among months Mārgaśīrṣa. All 42 ślokas in IAST, each on two pages.',
 burst='CHAPTER 10 OF 18',h1='DIVINE GLORIES',series='BHAGAVAD GĪTĀ · CHAPTER 10 · VIBHŪTI YOGA',tag='A spark of my splendour · every śloka explained',cover=cover,
 where=[f'In {chl(9)} Kṛṣṇa revealed the royal secret of devotion: offer a leaf with love, and he carries the rest.',
  'In chapter 10 Arjuna asks: where should I think of you? Kṛṣṇa names his glories, the best in every class, from the sun and Mount Meru to the letter A and the month of Mārgaśīrṣa. The lesson: wherever there is excellence, see a spark of the Divine.'],
 wtalk=("Why such a long list?","To train the eye. After this chapter, every sunrise and every great river can remind you."),
 fullnote=FULLNOTE,
 secs=[('THE SOURCE OF ALL',1),('THE FOUR CORE VERSES',8),('ARJUNA ASKS',12),('THE GLORIES',19),('A SPARK OF MY SPLENDOUR',39)],
 end=['<b>The source (10.1–7).</b> Not even the gods know his origin; every quality, pleasant or painful, comes from him.',
  '<b>Four core verses (10.8–11).</b> He is the origin of all; devotees delight together; he gives understanding and lights the lamp of knowledge in their hearts.',
  '<b>Arjuna asks (10.12–18).</b> You are the Supreme, as the sages say; tell me your glories; I never tire of this nectar.',
  '<b>The glories (10.19–38).</b> Viṣṇu, the sun, the Sāmaveda, Śiva, Meru, japa, the aśvattha, Prahlāda, Rāma, the Gaṅgā, A, Mārgaśīrṣa, Vyāsa, silence.',
  '<b>The rule (10.39–42).</b> Whatever is excellent is a spark of his splendour; the universe is one fragment of him.'],
 endsub='Chapter 10 in five lines',
 next=("What's next?",f'{chl(11)}: The cosmic form. Arjuna asks to see it, and Kṛṣṇa gives him divine eyes. What he sees is beautiful and terrifying: “I am Time, destroyer of worlds.”'),
 endkey='<b>all excellence is a spark of the Lord</b>.',
 foot=FOOT(10,'Identifications of mythic figures (Uccaiḥśravas, Kāmadhuk, the makara, etc.) follow the standard commentaries; readings of a few (e.g. Rāma in 10.31) differ. '))
build2(P)
